import React from "react";
import {
  AbsoluteFill,
  interpolate,
  spring,
  useCurrentFrame,
  useVideoConfig,
} from '../remotionShim';
{/* Start Google Fonts Loader */}
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map((f) => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(`link[href*="${font.replace(/\s+/g, "+")}"]`)
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map(
        (font) =>
          `family=${font.replace(
            /\s+/g,
            "+"
          )}:ital,wght@0,400;0,600;0,700;1,400;1,600;1,700`
      )
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */}



export type MarketingFunnelProps = Record<string, any>;

// Pre-defined layout and color constants based on the reference
const FUNNEL_LEVELS = 5;
const LEVEL_HEIGHT = 150;
const TOP_RX = 380;
const BOT_RX = 100;
const RX_STEP = (TOP_RX - BOT_RX) / FUNNEL_LEVELS;
const RY_RATIO = 0.22;

const LEVEL_COLORS = [
  { inner: "#9B72D3", outer: "#BCA3EA" }, // Purple
  { inner: "#64B5AD", outer: "#8ADCD3" }, // Teal
  { inner: "#6CBD5E", outer: "#96E187" }, // Green
  { inner: "#D8994E", outer: "#FAD38D" }, // Orange
  { inner: "#EC6786", outer: "#FCA2BA" }, // Pink
];

const MarketingFunnel: React.FC<MarketingFunnelProps> = ({
  backgroundColor = "#1E5AD6",
  transparentBackground = false,
  durationInSeconds = 10,
  funnelLabels = ["Awareness", "Interest", "Desire", "Action", ""],
  labelColor = "#ffffff",
  numberColor = "#ff8c00",
  shadowColor = "#0f388a",
  fontSize = 42,
}) => {
  useFontLoader(["Montserrat"]);

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Layout Calculations
  const cx = width * 0.35; // Shifted left to make room for labels and balance overall centering
  const startY = height / 2 - (FUNNEL_LEVELS * LEVEL_HEIGHT) / 2 + 30;
  
  const shadowOpacity = interpolate(frame, [0, 20], [0, 1], { extrapolateRight: "clamp" });
  const shadowScale = spring({ frame, fps, config: { damping: 14 } });

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily: "Montserrat" }}>
      {/* Funnel Shadow */}
      <svg width={width} height={height} style={{ position: "absolute", top: 0, left: 0 }}>
        <ellipse
          cx={cx}
          cy={startY + FUNNEL_LEVELS * LEVEL_HEIGHT + 20}
          rx={BOT_RX * 0.9 * shadowScale}
          ry={BOT_RX * RY_RATIO * 0.9 * shadowScale}
          fill={shadowColor}
          opacity={shadowOpacity}
        />
      </svg>

      {/* Funnel Levels - Rendered bottom-to-top so tops overlay correctly */}
      {LEVEL_COLORS.map((colors, i) => {
        // We draw from index 4 down to 0, but logical level is i
        const levelIndex = FUNNEL_LEVELS - 1 - i;
        const colorSet = LEVEL_COLORS[levelIndex];
        const label = funnelLabels[levelIndex];
        
        const topY = startY + levelIndex * LEVEL_HEIGHT;
        const rxTop = TOP_RX - levelIndex * RX_STEP;
        const rxBot = TOP_RX - (levelIndex + 1) * RX_STEP;
        const ryTop = rxTop * RY_RATIO;
        const ryBot = rxBot * RY_RATIO;

        // Animation timings
        // Stagger from top to bottom logically, so index 0 drops first
        const appearDelay = levelIndex * 10 + 15;
        const levelScale = spring({
          frame: frame - appearDelay,
          fps,
          config: { damping: 12, mass: 0.8 },
        });

        // Path for the front 3D body of the funnel segment
        const frontBodyPath = `
          M ${-rxTop} 0
          A ${rxTop} ${ryTop} 0 0 0 ${rxTop} 0
          L ${rxBot} ${LEVEL_HEIGHT}
          A ${rxBot} ${ryBot} 0 0 1 ${-rxBot} ${LEVEL_HEIGHT}
          Z
        `;

        const rxCenter = (rxTop + rxBot) / 2;

        // Line and Label Animation
        const lineDelay = appearDelay + 15;
        const lineProgress = spring({
          frame: frame - lineDelay,
          fps,
          config: { damping: 15 },
        });
        
        const labelOpacity = interpolate(frame - lineDelay - 5, [0, 10], [0, 1], { extrapolateRight: "clamp" });
        const labelTranslateX = interpolate(frame - lineDelay - 5, [0, 15], [30, 0], { extrapolateRight: "clamp" });

        const lineStartX = rxCenter + 20;
        const lineEndX = width * 0.65 - cx; // Target X coordinate relative to cx
        const lineY = LEVEL_HEIGHT * 0.5;

        // Skip line/label rendering if there's no text (e.g., pink level)
        // Check carefully to avoid runtime errors on undefined labels
        const hasLabel = Boolean(label && typeof label === "string" && label.trim() !== "");

        return (
          <AbsoluteFill key={`level-${levelIndex}`} style={{ transition: "none" }}>
            <svg width={width} height={height} style={{ overflow: "visible" }}>
              <g
                transform={`translate(${cx}, ${topY}) scale(${levelScale})`}
                style={{ transformOrigin: "0px 0px" }}
              >
                {/* Connecting Line */}
                {hasLabel && (
                  <line
                    x1={lineStartX}
                    y1={lineY}
                    x2={lineStartX + (lineEndX - lineStartX) * lineProgress}
                    y2={lineY}
                    stroke={shadowColor}
                    strokeWidth="3"
                    opacity={0.5}
                  />
                )}

                {/* Inner Top Ellipse (Darker) */}
                <ellipse
                  cx={0}
                  cy={0}
                  rx={rxTop}
                  ry={ryTop}
                  fill={colorSet.inner}
                />
                
                {/* Front Body Path (Lighter) */}
                <path
                  d={frontBodyPath}
                  fill={colorSet.outer}
                  stroke="rgba(0,0,0,0.05)"
                  strokeWidth="1"
                />

                {/* Text Label */}
                {hasLabel && (
                  <g
                    transform={`translate(${lineEndX + 20 + labelTranslateX}, ${lineY})`}
                    opacity={labelOpacity}
                  >
                    <text
                      x={0}
                      y={0}
                      dominantBaseline="central"
                      fill={numberColor}
                      fontSize={fontSize}
                      fontWeight="700"
                      fontStyle="italic"
                    >
                      {levelIndex + 1}
                    </text>
                    <text
                      x={fontSize * 1.1}
                      y={0}
                      dominantBaseline="central"
                      fill={labelColor}
                      fontSize={fontSize}
                      fontWeight="600"
                      fontStyle="italic"
                    >
                      {label}
                    </text>
                  </g>
                )}
              </g>
            </svg>
          </AbsoluteFill>
        );
      })}
    </AbsoluteFill>
  );
};

export default MarketingFunnel;